/* @autogenerated */
import { ResourceServerRepository } from 'app/features/access/resource-server/repository/resource-server-repository.service';
import { ResourceServer } from 'app/features/access/resource-server/model/resource-server.model';
import {
  RESOURCE_SERVER_EXCEL_COLUMNS,
  RESOURCE_SERVER_EXCEL_SENSITIVE,
} from 'app/features/access/resource-server/model/resource-server-excel-columns';
import { take, map } from 'rxjs';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { Component, inject } from '@angular/core';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'resource-server-view-import-action',
  standalone: false,
  templateUrl: './resource-server-view-import-action.component.html',
})
export class ResourceServerViewImportActionComponent extends BaseImportAction<ResourceServer> {
  protected readonly scope = 'access/resource-server';
  protected readonly repository = inject(ResourceServerRepository);

  readonly definition: ImportDefinition<ResourceServer> = {
    storageKey: 'access.resource-server',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['apiKey'],
    columns: RESOURCE_SERVER_EXCEL_COLUMNS,
    sensitive: RESOURCE_SERVER_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      enabled: [
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
      ],
    },
    defaults: () => ({ enabled: false }),
    display: (values) => String(values.code ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository.values({ apiKey: values.apiKey, limit: LOOKUP_LIMIT }).pipe(
          take(1),
          map((found) => found.filter((item) => item.apiKey === values.apiKey)),
        ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
